{"path": "parser.mjs", "content": "const SKU_RE = /^[A-Z][A-Z0-9-]*$/;
const DIGITS_RE = /^[0-9]+$/;

function parseField(raw, lineNumber, fieldName) {
  const value = raw.trim();
  if (!DIGITS_RE.test(value)) {
    throw new Error(`Malformed ${fieldName} on line ${lineNumber}: ${JSON.stringify(raw)}`);
  }
  const num = Number(value);
  if (!Number.isSafeInteger(num)) {
    throw new RangeError(`${fieldName} on line ${lineNumber} exceeds Number.MAX_SAFE_INTEGER`);
  }
  return num;
}

export function parseOrders(text) {
  if (typeof text !== 'string') {
    throw new TypeError('parseOrders expects a string');
  }
  const orders = [];
  const lines = text.split('\n');
  for (let i = 0; i < lines.length; i++) {
    const line = lines[i];
    if (line.trim() === '') continue;
    const fields = line.split(',');
    if (fields.length !== 3) {
      throw new Error(`Malformed row on line ${i + 1}: expected 3 fields`);
    }
    const sku = fields[0].trim();
    if (!SKU_RE.test(sku)) {
      throw new Error(`Malformed SKU on line ${i + 1}: ${JSON.stringify(fields[0])}`);
    }
    const quantity = parseField(fields[1], i + 1, 'quantity');
    if (quantity <= 0) {
      throw new Error(`Quantity on line ${i + 1} must be positive`);
    }
    const unitPriceCents = parseField(fields[2], i + 1, 'unitPriceCents');
    orders.push({ sku, quantity, unitPriceCents });
  }
  return orders;
}
