{"path": "report.mjs", "content": "import { parseOrders } from './parser.mjs';

const MAX = Number.MAX_SAFE_INTEGER;

function addSafe(a, b, label) {
  const sum = a + b;
  if (!Number.isSafeInteger(sum)) {
    throw new RangeError(`${label} exceeds Number.MAX_SAFE_INTEGER`);
  }
  return sum;
}

export function buildReport(text) {
  const rows = parseOrders(text);
  const bySku = new Map();
  let totalUnits = 0;
  let totalCents = 0;
  for (const row of rows) {
    const lineCents = row.quantity * row.unitPriceCents;
    if (!Number.isSafeInteger(lineCents)) {
      throw new RangeError(`Cents total for SKU ${row.sku} exceeds Number.MAX_SAFE_INTEGER`);
    }
    totalUnits = addSafe(totalUnits, row.quantity, 'Total units');
    totalCents = addSafe(totalCents, lineCents, 'Total cents');
    const existing = bySku.get(row.sku);
    if (existing) {
      existing.quantity = addSafe(existing.quantity, row.quantity, `Quantity for SKU ${row.sku}`);
      existing.totalCents = addSafe(existing.totalCents, lineCents, `Cents total for SKU ${row.sku}`);
    } else {
      bySku.set(row.sku, { sku: row.sku, quantity: row.quantity, totalCents: lineCents });
    }
  }
  const items = [...bySku.values()].sort((a, b) => (a.sku < b.sku ? -1 : a.sku > b.sku ? 1 : 0));
  return { items, totalUnits, totalCents };
}
"}

